package app

import org.jetbrains.exposed.v1.jdbc.Database

/** The database DATABASE_URL names (a JDBC URL), through Exposed. It never migrates: the database already exists. */
object AppDatabase {
    const val DEFAULT_URL = "jdbc:postgresql://localhost:5432/app"

    /** A connection to the database at url (DATABASE_URL, with DATABASE_USER and DATABASE_PASSWORD, by default). */
    fun connect(
        url: String = System.getenv("DATABASE_URL") ?: DEFAULT_URL,
        user: String = System.getenv("DATABASE_USER") ?: "",
        password: String = System.getenv("DATABASE_PASSWORD") ?: "",
    ): Database = Database.connect(url, user = user, password = password)
}

package app.common

import org.jetbrains.exposed.v1.core.Column
import org.jetbrains.exposed.v1.core.Table
import org.jetbrains.exposed.v1.core.VarCharColumnType
import org.postgresql.util.PGobject

/** A value of an enum of the database, kept as its text. */
class DatabaseEnumColumnType(private val sql: String, private val typeName: String) : VarCharColumnType() {
    override fun sqlType(): String = sql

    // PostgreSQL takes a value of the enum, not a text
    override fun notNullValueToDB(value: String): Any = PGobject().also {
        it.type = typeName
        it.value = value
    }

    override fun valueFromDB(value: Any): String = if (value is PGobject) value.value!! else value.toString()
}

/** A column of an enum of the database. */
fun Table.databaseEnum(name: String, sql: String, typeName: String): Column<String> =
    registerColumn(name, DatabaseEnumColumnType(sql, typeName))

