)

package app.entities

import org.jetbrains.exposed.v1.core.ReferenceOption
import org.jetbrains.exposed.v1.core.Table

/**
 * The "entries" table, as the database has it. Exposed never creates or changes it: the database already exists.
 */
object EntryTable : Table("audit.entries") {
    val entryNo = integer("entry_no").autoIncrement()
    val orderId = long("orderId")
    val message = varchar("message", 200)

    override val primaryKey = PrimaryKey(entryNo)

    init {
        foreignKey(orderId to OrderTable.id, onDelete = ReferenceOption.CASCADE)
    }
}

