package app.repositories

import app.common.Page
import app.entities.Empty
import app.entities.EmptyTable
import app.errors.ConflictException
import org.jetbrains.exposed.v1.core.ResultRow
import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.exceptions.ExposedSQLException
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.deleteWhere
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction
import org.jetbrains.exposed.v1.jdbc.update

/** Keeps empties rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlEmptyRepository(private val db: Database) : EmptyRepository {
    override fun findById(id: Long): Empty? {
        return exposedTransaction(db) {
            EmptyTable.selectAll().where { EmptyTable.id eq id }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<Empty> {
        return exposedTransaction(db) {
            val query = EmptyTable.selectAll()
            val total = query.count()
            val items = query.orderBy(EmptyTable.id to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun insert(entity: Empty): Empty {
        return write {
            val statement = EmptyTable.insert { row ->
                entity.note?.let { row[EmptyTable.note] = it }
            }
            entity.id = statement[EmptyTable.id]
            fill(entity, EmptyTable.selectAll().where { EmptyTable.id eq entity.id!! }.single())
            entity
        }
    }

    override fun update(entity: Empty): Empty {
        return write {
            EmptyTable.update({ EmptyTable.id eq entity.id!! }) { row ->
                row[EmptyTable.note] = entity.note
            }
            entity
        }
    }

    override fun delete(entity: Empty): Unit {
        write {
            EmptyTable.deleteWhere { EmptyTable.id eq entity.id!! }
        }
    }

    private fun toEntity(row: ResultRow): Empty = Empty().also { fill(it, row) }

    private fun fill(entity: Empty, row: ResultRow) {
        entity.id = row[EmptyTable.id]
        entity.note = row[EmptyTable.note]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("Empty", "the database refused the change: ${error.cause?.message}")
        }
}

