/** Where things rows are kept. Services depend only on this interface. */
interface ThingRepository {
    /** The row with this primary key, or null. */
    fun findById(id: UUID): Thing?

    /** At most limit rows from offset, by primary key, and how many there are. */
    fun list(offset: Int, limit: Int): Page<Thing>

    /** Stores a new row; the values the database fills are read back. */
    fun insert(entity: Thing): Thing

    /** Stores the changes made to a row. */
    fun update(entity: Thing): Thing

    /** Removes a row. */
    fun delete(entity: Thing): Unit
