package app.services

import app.UnitOfWork
import app.common.Page
import app.dtos.EmptyCreate
import app.dtos.EmptyRead
import app.dtos.EmptyUpdate
import app.entities.Empty
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on empties. Each write runs in its own transaction. */
class EmptyService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Empty after checking it. */
    fun createEmpty(data: EmptyCreate): EmptyRead {
        val values = mapOf(
            "note" to data.note,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Empty()
            applyValues(entity, values)
            read(uow.empties.insert(entity))
        }
    }

    /** The Empty with this key; NotFoundException when there is none. */
    fun getEmpty(id: Long): EmptyRead = read(find(unitOfWork, id))

    /** A page of empties, by primary key. */
    fun listEmpties(offset: Int, limit: Int): Page<EmptyRead> = unitOfWork.empties.list(offset, limit).map { read(it) }

    /** Changes the given values of a Empty. */
    fun updateEmpty(id: Long, changes: EmptyUpdate): EmptyRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.empties.update(current))
        }
    }

    /** Deletes a Empty. */
    fun deleteEmpty(id: Long) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.empties.delete(current)
        }
    }

    /** Checks the values against the rules of the "empties" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Empty?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        if (errors.isNotEmpty()) throw ValidationFailedException("Empty", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Empty?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Empty, values: Map<String, Any?>) {
        if ("note" in values) entity.note = values["note"] as String?
    }

    /** The Empty with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Empty =
        uow.empties.findById(id) ?: throw NotFoundException("Empty", id)

    /** The Empty as services return it. */
    private fun read(entity: Empty): EmptyRead =
        EmptyRead(
            id = entity.id!!,
            note = entity.note,
        )

    /** The values an update gives, by field. */
    private fun given(changes: EmptyUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.note.isPresent) values["note"] = changes.note.value
        return values
    }
}

