    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Entry?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["orderId"]
            if (value == null) {
                if (creating || "orderId" in values) errors += FieldError("orderId", "is required")
            }
        }
        run {
            val value = values["message"]
            if (value == null) {
                if (creating || "message" in values) errors += FieldError("message", "is required")
            } else {
                if (value is String && value.length > 200) errors += FieldError("message", "is longer than 200 characters")
            }
        }
        run {
            val orderId = if ("orderId" in values) values["orderId"] as Long? else current?.orderId
            if (orderId != null && uow.order.findById(orderId) == null)
                errors += FieldError("orderId", "no Order has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Entry", errors)
    }

