    private fun applyValues(entity: Entry, values: Map<String, Any?>) {
        if ("orderId" in values) entity.orderId = values["orderId"] as Long?
        if ("message" in values) entity.message = values["message"] as String?
    }

    /** The Entry with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, entryNo: Int): Entry =
        uow.entries.findByEntryNo(entryNo) ?: throw NotFoundException("Entry", entryNo)

    /** The Entry as services return it. */
    private fun read(entity: Entry): EntryRead =
        EntryRead(
            entryNo = entity.entryNo!!,
