/** Operations on Order. Each write runs in its own transaction. */
class OrderService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Order after checking it. */
    fun createOrder(data: OrderCreate): OrderRead {
        val values = mapOf(
            "user" to data.user,
            "group" to data.group,
            "customerName" to data.customerName,
            "class" to data.`class`,
            "metadata" to data.metadata,
            "date" to data.date,
            "time" to data.time,
            "text" to data.text,
            "list" to data.list,
            "str" to data.str,
            "int" to data.int,
            "dueDate" to data.dueDate,
            "closesAt" to data.closesAt,
            "kindCode" to data.kindCode,
            "kindDay" to data.kindDay,
            "thingId" to data.thingId,
            "parentId" to data.parentId,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Order()
            applyValues(entity, values)
            read(uow.order.insert(entity))
        }
    }

    /** The Order with this key; NotFoundException when there is none. */
    fun getOrder(id: Long): OrderRead = read(find(unitOfWork, id))

    /** A page of Order, by primary key. */
    fun listOrders(offset: Int, limit: Int): Page<OrderRead> = unitOfWork.order.list(offset, limit).map { read(it) }

    /** Changes the given values of a Order. */
    fun updateOrder(id: Long, changes: OrderUpdate): OrderRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.order.update(current))
        }
    }

    /** Deletes a Order. */
    fun deleteOrder(id: Long) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.order.listByParentId(current.id!!).isNotEmpty())
                throw ConflictException("Order", "rows of Order still point to it", listOf("Order"))
            uow.order.delete(current)
        }
    }

    /** The Order with this customerName, or null. */
    fun findOrderByCustomerName(customerName: String): OrderRead? = unitOfWork.order.findByCustomerName(customerName)?.let { read(it) }

    /** The Order with this thing_id. */
    fun listOrdersByThingId(thingId: UUID): List<OrderRead> = unitOfWork.order.listByThingId(thingId).map { read(it) }

    /** The Order with this parentId. */
    fun listOrdersByParentId(parentId: Long): List<OrderRead> = unitOfWork.order.listByParentId(parentId).map { read(it) }

    /** The Order with this kind_code and kind_day. */
    fun listOrdersByKindCodeAndKindDay(kindCode: String, kindDay: LocalDate): List<OrderRead> = unitOfWork.order.listByKindCodeAndKindDay(kindCode, kindDay).map { read(it) }

    /** Checks the values against the rules of the "Order" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["user"]
            if (value == null) {
                if (creating || "user" in values) errors += FieldError("user", "is required")
            } else {
                if (value is String && value.length > 40) errors += FieldError("user", "is longer than 40 characters")
            }
        }
        run {
            val value = values["group"]
            if (value == null) {
                if (!creating && "group" in values) errors += FieldError("group", "cannot be empty")
            } else {
                if (!((value as Number).toDouble() >= 0.0)) errors += FieldError("group", "must be >= 0")
            }
        }
        run {
            val value = values["customerName"]
            if (value == null) {
                if (creating || "customerName" in values) errors += FieldError("customerName", "is required")
            } else {
                if (value is String && value.length > 60) errors += FieldError("customerName", "is longer than 60 characters")
            }
        }
        run {
            val value = values["text"]
            if (value != null) {
                if (value is String && value.length > 20) errors += FieldError("text", "is longer than 20 characters")
            }
        }
        run {
            val value = values["str"]
            if (value != null) {
                if (value is String && value.length > 10) errors += FieldError("str", "is longer than 10 characters")
            }
        }
        run {
            val value = values["dueDate"]
            if (value == null) {
                if (creating || "dueDate" in values) errors += FieldError("dueDate", "is required")
            }
        }
        run {
            val value = values["kindCode"]
            if (value != null) {
                if (value is String && value.length > 10) errors += FieldError("kind_code", "is longer than 10 characters")
            }
        }
        run {
            val thingId = if ("thingId" in values) values["thingId"] as UUID? else current?.thingId
            if (thingId != null && uow.things.findById(thingId) == null)
                errors += FieldError("thing_id", "no Thing has this key")
        }
        run {
            val parentId = if ("parentId" in values) values["parentId"] as Long? else current?.parentId
            if (parentId != null && uow.order.findById(parentId) == null)
                errors += FieldError("parentId", "no Order has this key")
        }
        run {
            val kindCode = if ("kindCode" in values) values["kindCode"] as String? else current?.kindCode
            val kindDay = if ("kindDay" in values) values["kindDay"] as LocalDate? else current?.kindDay
            if (kindCode != null && kindDay != null && uow.kinds.findByCodeAndDay(kindCode, kindDay) == null)
                errors += FieldError("kind_code, kind_day", "no Kind has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Order", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        run {
            val customerName = if ("customerName" in values) values["customerName"] as String? else current?.customerName
            if (customerName != null) {
                val other = uow.order.findByCustomerName(customerName)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Order", "customerName is already taken", listOf("customerName"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Order, values: Map<String, Any?>) {
        if ("user" in values) entity.user = values["user"] as String?
        if ("group" in values) entity.group = values["group"] as Int?
        if ("customerName" in values) entity.customerName = values["customerName"] as String?
        if ("class" in values) entity.`class` = values["class"] as String?
        if ("metadata" in values) entity.metadata = values["metadata"] as String?
        if ("date" in values) entity.date = values["date"] as LocalDate?
        if ("time" in values) entity.time = values["time"] as LocalTime?
        if ("text" in values) entity.text = values["text"] as String?
        if ("list" in values) entity.list = values["list"] as String?
        if ("str" in values) entity.str = values["str"] as String?
        if ("int" in values) entity.int = values["int"] as Int?
        if ("dueDate" in values) entity.dueDate = values["dueDate"] as LocalDate?
        if ("closesAt" in values) entity.closesAt = values["closesAt"] as LocalTime?
        if ("kindCode" in values) entity.kindCode = values["kindCode"] as String?
        if ("kindDay" in values) entity.kindDay = values["kindDay"] as LocalDate?
        if ("thingId" in values) entity.thingId = values["thingId"] as UUID?
        if ("parentId" in values) entity.parentId = values["parentId"] as Long?
    }

    /** The Order with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Order =
        uow.order.findById(id) ?: throw NotFoundException("Order", id)

    /** The Order as services return it. */
    private fun read(entity: Order): OrderRead =
